750		ctx := context.Background()
751	
752		// Two decreases are registered while nothing is occupied; both are due
753		// immediately. The first applies, the second would crowd out the quota
754		// later confirmed against the reduced total.
755		if _, _, err := store.CreateAdjustment(ctx, id, "adj-cut-1", -40, time.Now().Add(-time.Minute)); err != nil {
