763		if view.QuotaTotal != 20 {
764			t.Fatalf("quota after two decreases: %+v", view)
765		}
766	
767		// Occupy the reduced total fully, then register another decrease: it
768		// must stay pending while used plus reserved exceeds the adjusted total.
769		if _, _, err := store.CreateReservation(ctx, id, "res-1", 20); err != nil {
770			t.Fatalf("reserve: %v", err)
771		}
772		if _, err := store.SettleReservation(ctx, id, "res-1", ActionConfirm); err != nil {
773			t.Fatalf("confirm: %v", err)
774		}
775		third, _, err := store.CreateAdjustment(ctx, id, "adj-cut-3", -10, time.Now().Add(-time.Minute))
776		if err != nil || third.Status != StatusPending {
777			t.Fatalf("third decrease should be blocked: %+v err=%v", third, err)
778		}
779		view, _ = store.GetView(ctx, id)
780		if view.QuotaTotal != 20 || view.UsedAmount != 20 || view.AvailableAmount != 0 {
781			t.Fatalf("blocked decrease crowded out occupied quota: %+v", view)
782		}
783	}
